import sys

def print_inverted_half_pyramid(R):
    for i in range(R, 0, -1):
        if i == R:
            # Top row: all numbers 1 to R
            print(''.join(str(d) for d in range(1, R + 1)) + ' ')
        elif i == 1:
            # Bottom row: just 1
            print('1')
        else:
            # Middle rows: hollow pattern
            # Numbers are 1, i, so print "1" + " " + str(i)
            print('1 ' + str(i))

def main():
    R = int(sys.stdin.readline().strip())
    print_inverted_half_pyramid(R)

if __name__ == "__main__":
    main()
